"""Picture and file fields the API shows and accepts (generated by Shikshya, P1b.6 R2). A seeded picture (a path
from the built frontend such as /img/dish/soup.jpg, a full address, or a data: URI) is shown as it is; an upload is
shown through its storage (a signed link from a bucket, or /media/... on one server). A new file from a staff form
is saved like any upload; an address or an empty value sent back by an edit form leaves the stored picture as it is."""
from rest_framework import serializers

PASSTHROUGH = ("http", "data:", "/")


class _StoredMixin:
    def to_representation(self, value):
        if not value:
            return None
        text = str(value)
        if text.startswith(PASSTHROUGH):
            return text
        return super().to_representation(value)

    def validate_empty_values(self, data):
        if data is None or isinstance(data, str):
            raise serializers.SkipField()
        return super().validate_empty_values(data)


class PictureField(_StoredMixin, serializers.ImageField):
    pass


class StoredFileField(_StoredMixin, serializers.FileField):
    pass
